// CommDSP-Bench: cmul anchor task — Karatsuba (3-mult) complex multiplier
//
// 用 3 个乘法器实现复数乘法（Karatsuba 技巧），减少 LUT 面积：
//   y_re = a*c - b*d
//   y_im = (a+b)*(c+d) - a*c - b*d

module top (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire signed [15:0] a,
    input  wire signed [15:0] b,
    input  wire signed [15:0] c,
    input  wire signed [15:0] d,
    output reg                out_valid,
    input  wire               out_ready,
    output reg  signed [32:0] y_re,
    output reg  signed [32:0] y_im
);

    // EVOLVE-BLOCK-START
    // 符号扩展到 17 bit（a+b 范围 -65536..65534）
    wire signed [16:0] a17 = {a[15], a};
    wire signed [16:0] b17 = {b[15], b};
    wire signed [16:0] c17 = {c[15], c};
    wire signed [16:0] d17 = {d[15], d};

    wire signed [16:0] ab = a17 + b17;   // a+b
    wire signed [16:0] cd = c17 + d17;   // c+d

    // 3 个乘法器
    wire signed [31:0] ac = a * c;
    wire signed [31:0] bd = b * d;
    wire signed [33:0] sm = ab * cd;     // (a+b)*(c+d)

    // y_re = ac - bd   （结果落在 32bit 有符号范围内，符号扩展即可）
    wire signed [32:0] re_n = ac - bd;

    // y_im = (a+b)*(c+d) - ac - bd  （34bit 中间运算，取低 33bit）
    wire signed [33:0] im_n = sm - {{2{ac[31]}}, ac} - {{2{bd[31]}}, bd};

    assign in_ready = 1'b1;

    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            y_re      <= 33'sd0;
            y_im      <= 33'sd0;
        end else begin
            if (in_valid && in_ready) begin
                y_re      <= re_n;
                y_im      <= im_n[32:0];
                out_valid <= 1'b1;
            end else if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
        end
    end
    // EVOLVE-BLOCK-END

